package com.yeyamo_mobile.api.admin_service.governance;
import static com.yeyamo_mobile.api.admin_service.governance.GovernanceDtos.*;import java.util.*;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/admin")@PreAuthorize("hasRole('SUPER_ADMIN')")public class GovernanceController{
 private final GovernanceService service;public GovernanceController(GovernanceService s){service=s;}
 @GetMapping("/settings")public List<SettingResponse>settings(){return service.settings();}@PutMapping("/settings/{key}")public SettingResponse setting(@PathVariable String key,@Valid@RequestBody SettingUpdateRequest r,HttpServletRequest req){return service.updateSetting(key,r,req);}@GetMapping("/settings/history")public List<SettingResponse>history(){return service.settingHistory();}@PostMapping("/settings/{key}/rollback/{version}")public SettingResponse rollback(@PathVariable String key,@PathVariable long version,@RequestParam String reason,HttpServletRequest req){return service.rollbackSetting(key,version,reason,req);}
 @GetMapping("/feature-flags")public List<FeatureFlagResponse>flags(){return service.flags();}@GetMapping("/feature-flags/{key}")public FeatureFlagResponse flag(@PathVariable String key){return service.flag(key);}@PostMapping("/feature-flags")public FeatureFlagResponse create(@Valid@RequestBody FeatureFlagRequest r,HttpServletRequest req){return service.create(r,req);}@PutMapping("/feature-flags/{key}")public FeatureFlagResponse update(@PathVariable String key,@Valid@RequestBody FeatureFlagRequest r,HttpServletRequest req){return service.updateFlag(key,r,req);}@GetMapping("/feature-flags/{key}/history")public List<FeatureFlagResponse>flagHistory(@PathVariable String key){return service.flagHistory(key);}@PostMapping("/feature-flags/{key}/rollback/{version}")public FeatureFlagResponse rollbackFlag(@PathVariable String key,@PathVariable long version,@RequestParam String reason,HttpServletRequest req){return service.rollbackFlag(key,version,reason,req);}
}
